import{_ as e,o as a,c as i,a0 as o}from"./chunks/framework.C0WKPwzJ.js";const u=JSON.parse('{"title":"Install the Autodevelop GitHub App","description":"Connect GitHub from the operator console so Autodevelop can use the organization board and repositories.","frontmatter":{"title":"Install the Autodevelop GitHub App","description":"Connect GitHub from the operator console so Autodevelop can use the organization board and repositories."},"headers":[],"relativePath":"github.md","filePath":"github.md","lastUpdated":1788171427000}'),s={name:"github.md"};function n(l,t,r,p,h,d){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="github-app" tabindex="-1">GitHub App <a class="header-anchor" href="#github-app" aria-label="Permalink to &quot;GitHub App&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>Autodevelop uses a GitHub App on your organization. Agents then act with a short-lived installation token, not a personal <code>gh</code> login. Sign-in to Autodevelop stays email and password (<a href="./cli">CLI</a>). GitHub is a connected install.</p><h2 id="who-installs-it" tabindex="-1">Who installs it <a class="header-anchor" href="#who-installs-it" aria-label="Permalink to &quot;Who installs it&quot;">​</a></h2><p>An operator with organization management signs in to the <strong>operator console</strong> and opens <strong>Connect GitHub</strong>.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Sign in to the operator console.</li><li>Open <strong>Connect GitHub</strong>.</li><li>GitHub shows the Autodevelop App install screen. Choose the GitHub organization.</li><li>Choose all repositories or selected repositories.</li><li>Finish the hosted wizard: Project, status and priority fields, and invites.</li><li>Save. Autodevelop stores the installation and board field ids.</li></ol><p>The installer picks the repository set on GitHub’s screen. Autodevelop does not ask for administration or secrets permissions.</p><h2 id="after-install" tabindex="-1">After install <a class="header-anchor" href="#after-install" aria-label="Permalink to &quot;After install&quot;">​</a></h2><p>Developers on that organization run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> token</span></span></code></pre></div><p>The CLI prints when the token expires and which account it is for. It does not print the token. Use it so <code>gh</code> acts as the Autodevelop GitHub App.</p><p>If the hosted wizard has not written field ids yet, an operator can still bind the Project by hand or with the bootstrap fallback (<a href="./configure">Configure</a>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./cli">CLI</a></li><li><a href="./workflows/initial-setup">Initial setup</a></li><li><a href="./configure">Configure</a></li></ul>',15)])])}const b=e(s,[["render",n]]);export{u as __pageData,b as default};
